                    const doorBottom = Heatline.box(b.x, .14, front - .24, doorW + .50, .12, .64, C.wall);
                    doorBottom.material = 'concrete';
                    this.add(doorBottom);
                    checked(doorBottom, 'front', 'entry threshold', .14);
                    // Shallow handrails are attached to the glass entry surface.
                    const handle = Heatline.box(b.x + .24, 1.40, front - .36, .065, .44, .06, '#dfd6bc', 0, 5, .06);
                    handle.material = 'metal';
