                        const rail = Heatline.box(cx, yy + .60, outward, span - .14, 1.03, .095, C.rail, 0, 5, .07);
                        rail.material = 'glass';
                        this.add(rail);
                        const cap = Heatline.box(cx, yy + 1.14, outward, span + .09, .085, .14, C.dark);
                        cap.material = 'metal';
                        this.add(cap);
                        for (const end of [-1, 1]) {
                            const xx = cx + end * (span * .5 - .11);
                            const post = Heatline.box(xx, yy + .58, outward, .09, 1.09, .14, C.dark);
                            post.material = 'metal';
                            this.add(post);
                            // Structural brackets join the slab to the facade instead of
                            // leaving a balcony floating beyond the wall.
                            const support = Heatline.box(xx, yy - .22, plane + side * .40, .17, .44, .85, C.dark);
                            support.material = 'metal';
                            this.add(support);
                            checked(support, side < 0 ? 'front' : 'rear', 'balcony bracket', yy - .22);
                        }
