                    parapet.material = glassy ? 'metal' : 'concrete';
                    this.add(parapet);
                    const parapetSide = Heatline.box(faceX(side) + side * .005, cy, b.z, .26, rh, b.d + .30, C.trim);
                    parapetSide.material = glassy ? 'metal' : 'concrete';
