            sub.textContent='רמת חיפוש '+level+' · קנס '+fine+' קרדיטים · '+charges+
                (impounded?' · הרכב הגנוב הוחרם':'')+' · שוחררת ליד תחנת המשטרה';
            screen.classList.add('visible');
