            if(id.clothingUntil>now)clues.push('🧥 לבוש');
            if(id.carUntil>now && id.carRef===this.player)clues.push('🚘 רכב');
            if(id.cameraUntil>now)clues.push('📷 מצלמה');
            intel.textContent=clues.length?'מידע שבידי המשטרה: '+clues.join(' · '):
                pending?'עדיין אין תיאור מאומת':'לא נותר תיאור זמין';
            surrender.hidden=!(this.crimeHeat>0 && this.crimeHeat<5 && !this.inVehicle && !this.inside);
