                const at = post.offsets.map(([dx,dz])=>({x:post.point.x+dx,z:post.point.z+dz}))
                    .find(({x,z})=>this.walkerPositionFree(x,z)
                        && this.officers.every(o=>Math.hypot(o.walker.x-x,o.walker.z-z)>4));
                if (!at) continue;
