                car.speed = 14;
                car.vx = -Math.sin(yaw) * 14;
                car.vz = -Math.cos(yaw) * 14;
                if (this.world.nearby(x, z).some(s => Heatline.carBuildingContact(car, s)))
                    continue;
                if (this.civilian.some(other => Math.hypot(other.x - x, other.z - z) < 8))
                    continue;
                this.civilian.push(car);
