        spawnPolice() {
            // Save up to two slots for a physical high-alert blockade later; total is
            // still restricted by patrolCap and no additional cars spawn on camera.
            const normalCap = this.heat >= 5 && this.dispatchedRoadblocks === 0 ? 4 : Heatline.patrolCap(this.heat);
            if (this.heat <= 0 || this.police.length >= normalCap)
                return false;
            const target = this.inVehicle ? this.player : this.avatar;
            const origin = this.policeRadio.reportedAt >= 0 ? { x: this.policeRadio.lastKnownX, z: this.policeRadio.lastKnownZ } : target;
            // Place response units on actual roads at distance and OUTSIDE the active camera.
            // Never teleport a squad on top of the player or stack cars at one coordinate.
            for (let attempt = 0; attempt < 10; attempt++) {
                const p = Heatline.initialPolicePosition(origin.x, origin.z, this.rng, this.inVehicle ? 185 : 160);
                const d = Math.hypot(p.x - target.x, p.z - target.z), viewDist = Math.hypot(p.x - this.cam.x, p.z - this.cam.z);
                if (d < 118 || viewDist < 105 || !Heatline.policeSafeSpawn(p.x, p.z, this.cam, target) ||
                    this.police.some(c => Math.hypot(p.x - c.x, p.z - c.z) < 35) ||
                    this.civilian.some(c => Math.hypot(p.x - c.x, p.z - c.z) < 7) ||
                    this.buses.some(b => Math.hypot(b.x - p.x, b.z - p.z) < 12) ||
                    this.trams.some(t => Math.hypot(t.x - p.x, t.z - p.z) < 32))
                    continue;
                const proxy = Heatline.makeCar('police', p.x, p.z, p.yaw, 0);
                if (this.world.nearby(p.x, p.z).some(s => Heatline.carBuildingContact(proxy, s)))
                    continue;
                proxy.hp = 75;
                proxy.pursuitRole = this.police.length % 3 === 0 ? 'intercept' : 'chase';
                proxy.sirenPhase = this.police.length * .71;
                this.police.push(proxy);
                this.officers.push(Heatline.makePoliceOfficer(proxy, this.officerNextId++));
                return true;
            }
            return false;
        }
