            const sx = this.avatar.x + d.x * .53 + Math.cos(yaw) * .19, sz = this.avatar.z + d.z * .53 - Math.sin(yaw) * .19;
            return this.fireWorldRay({ x: sx, y: 1.64, z: sz }, d);
